"""指标库写路径门禁（G4 published 四件套 + G5 先拆后 primary）。

权威：docs/metric_library_concept_model_v0.2_20260817.md §3
主人定稿 D5=a（2026-09-05）：上线前必须落地写路径校验。
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Optional, Sequence

# G2 / #6552 aggregation 白名单（derived 的 default_aggregation 须留空）
AGG_WHITELIST = frozenset({"sum", "count", "bitmap_union_count", "max", "min"})

# 旧 metric_standard 扫表白名单外常见脏值，publish 时一律拦截
LEGACY_AGG_BLOCKLIST = frozenset({"avg", "ratio", "count_distinct", "mean"})


@dataclass
class GateIssue:
    code: str  # G4_DEFINITION / G4_REQ_REF / G4_ACTIVE_IMPL / G4_AGG / G4_ENTITY / G5_DIVERGED_PRIMARY / ...
    message: str


@dataclass
class GateResult:
    ok: bool
    issues: list[GateIssue] = field(default_factory=list)

    def raise_if_failed(self) -> None:
        if self.ok:
            return
        detail = "; ".join(f"[{i.code}] {i.message}" for i in self.issues)
        raise ValueError(f"指标库门禁未通过：{detail}")


def _nonempty(s: Optional[str]) -> bool:
    return bool((s or "").strip())


def check_aggregation(agg: Optional[str], *, metric_kind: str = "atomic") -> list[GateIssue]:
    issues: list[GateIssue] = []
    a = (agg or "").strip()
    if metric_kind == "derived":
        if a:
            issues.append(
                GateIssue(
                    "G4_AGG",
                    f"derived 指标 default_aggregation 须留空（由分子/分母表达），当前={a!r}",
                )
            )
        return issues
    if not a:
        issues.append(GateIssue("G4_AGG", "atomic 指标缺少 default_aggregation / aggregation"))
        return issues
    if a not in AGG_WHITELIST:
        issues.append(
            GateIssue(
                "G4_AGG",
                f"aggregation={a!r} 不在白名单 {sorted(AGG_WHITELIST)}",
            )
        )
    return issues


def validate_concept_publish(
    *,
    concept_code: str,
    definition: Optional[str],
    req_ref: Optional[str],
    metric_kind: str,
    default_aggregation: Optional[str],
    numerator_concept_code: Optional[str],
    denominator_concept_code: Optional[str],
    entity_code: Optional[str],
    main_event_code: Optional[str],
    active_impl_count: int,
    diverged_pending_count: int,
) -> GateResult:
    """G4 + G5（发布前）：有 diverged_pending 不可 published。"""
    issues: list[GateIssue] = []
    if not _nonempty(definition):
        issues.append(GateIssue("G4_DEFINITION", f"{concept_code}: definition 不能为空"))
    if not _nonempty(req_ref):
        issues.append(GateIssue("G4_REQ_REF", f"{concept_code}: req_ref 不能为空"))
    if active_impl_count < 1:
        issues.append(
            GateIssue("G4_ACTIVE_IMPL", f"{concept_code}: 至少需要 1 条 active implementation")
        )
    kind = (metric_kind or "atomic").strip() or "atomic"
    if kind == "derived":
        if not (_nonempty(numerator_concept_code) and _nonempty(denominator_concept_code)):
            issues.append(
                GateIssue(
                    "G4_DERIVED_FK",
                    f"{concept_code}: derived 必须同时有 numerator_concept_code 与 denominator_concept_code",
                )
            )
        issues.extend(check_aggregation(default_aggregation, metric_kind="derived"))
    else:
        issues.extend(check_aggregation(default_aggregation, metric_kind="atomic"))
    if not _nonempty(entity_code):
        issues.append(GateIssue("G4_ENTITY", f"{concept_code}: entity_code 不能为空"))
    if not _nonempty(main_event_code):
        issues.append(GateIssue("G4_MAIN_EVENT", f"{concept_code}: main_event_code 不能为空"))
    if diverged_pending_count > 0:
        issues.append(
            GateIssue(
                "G5_DIVERGED",
                f"{concept_code}: 仍有 {diverged_pending_count} 条 diverged_pending，禁止 published（先拆/收敛）",
            )
        )
    return GateResult(ok=not issues, issues=issues)


def validate_set_primary(
    *,
    concept_code: str,
    diverged_pending_count: int,
) -> GateResult:
    """G5：存在 diverged_pending 时禁止设 is_primary。"""
    issues: list[GateIssue] = []
    if diverged_pending_count > 0:
        issues.append(
            GateIssue(
                "G5_DIVERGED_PRIMARY",
                f"{concept_code}: 存在 diverged_pending={diverged_pending_count}，禁止设 is_primary（先拆后 primary）",
            )
        )
    return GateResult(ok=not issues, issues=issues)


_REQ_REF_IN_NOTE = re.compile(r"(?:^|\s)req_ref\s*=\s*\S+", re.I)


def validate_legacy_standard_publish(
    *,
    name: str,
    formula: Optional[str],
    aggregation: Optional[str],
    note: Optional[str],
    active_binding_count: int,
) -> GateResult:
    """旧 metric_standard 发布门禁（过渡）：formula + 绑定 + 聚合白名单；req_ref 写在 note。"""
    issues: list[GateIssue] = []
    if not _nonempty(formula):
        issues.append(GateIssue("G4_FORMULA", f"{name}: formula 不能为空"))
    if active_binding_count < 1:
        issues.append(GateIssue("G4_BINDING", f"{name}: 至少需要 1 条 is_active 绑定"))
    agg = (aggregation or "").strip()
    if agg in LEGACY_AGG_BLOCKLIST or (agg and agg not in AGG_WHITELIST):
        issues.append(
            GateIssue(
                "G4_AGG",
                f"{name}: aggregation={agg!r} 不允许；白名单={sorted(AGG_WHITELIST)}",
            )
        )
    if not agg:
        issues.append(GateIssue("G4_AGG", f"{name}: aggregation 不能为空"))
    if not _REQ_REF_IN_NOTE.search(note or ""):
        issues.append(
            GateIssue(
                "G4_REQ_REF",
                f"{name}: note 须含 req_ref=...（旧表无独立列；例 req_ref=legacy:metric_standard/{name}）",
            )
        )
    return GateResult(ok=not issues, issues=issues)


def format_issues(issues: Sequence[GateIssue]) -> str:
    return "; ".join(f"[{i.code}] {i.message}" for i in issues)

"""指标库概念层查询 + 写路径（带 G4/G5 门禁）。

读：字典 / concept 列表。
写：publish_concept / set_implementation_primary —— 必须过 metric_gate。
"""
from __future__ import annotations

from datetime import datetime, timezone
from typing import Optional

from sqlmodel import Session, select

from app.models.metric_concept_layer import (
    EntityDict,
    EventExt,
    MetricConcept,
    MetricImplementation,
    RoleDict,
)
from app.models.user import User
from app.services import metric_gate


def list_entities(session: Session, status: Optional[str] = None, limit: int = 100) -> list[EntityDict]:
    stmt = select(EntityDict)
    if status:
        stmt = stmt.where(EntityDict.status == status)
    return list(session.exec(stmt.limit(limit)).all())


def get_entity(session: Session, entity_code: str) -> Optional[EntityDict]:
    return session.get(EntityDict, entity_code)


def list_roles(session: Session, status: Optional[str] = None, limit: int = 100) -> list[RoleDict]:
    stmt = select(RoleDict)
    if status:
        stmt = stmt.where(RoleDict.status == status)
    return list(session.exec(stmt.limit(limit)).all())


def get_role(session: Session, role_code: str) -> Optional[RoleDict]:
    return session.get(RoleDict, role_code)


def list_event_ext(
    session: Session,
    entity_code: Optional[str] = None,
    limit: int = 200,
) -> list[EventExt]:
    stmt = select(EventExt)
    if entity_code:
        stmt = stmt.where(EventExt.entity_code == entity_code)
    return list(session.exec(stmt.limit(limit)).all())


def get_event_ext(session: Session, event_code: str) -> Optional[EventExt]:
    return session.get(EventExt, event_code)


def list_concepts(
    session: Session,
    q: Optional[str] = None,
    lifecycle_status: Optional[str] = None,
    entity_code: Optional[str] = None,
    limit: int = 100,
) -> list[MetricConcept]:
    stmt = select(MetricConcept)
    if lifecycle_status:
        stmt = stmt.where(MetricConcept.lifecycle_status == lifecycle_status)
    if entity_code:
        stmt = stmt.where(MetricConcept.entity_code == entity_code)
    if q:
        like = f"%{q}%"
        stmt = stmt.where(
            (MetricConcept.concept_code.like(like))  # type: ignore[attr-defined]
            | (MetricConcept.definition.like(like))  # type: ignore[attr-defined]
        )
    return list(session.exec(stmt.limit(limit)).all())


def get_concept(session: Session, concept_code: str) -> Optional[MetricConcept]:
    return session.get(MetricConcept, concept_code)


def _impl_counts(session: Session, concept_code: str) -> tuple[int, int]:
    rows = list(
        session.exec(
            select(MetricImplementation).where(
                MetricImplementation.concept_code == concept_code
            )
        ).all()
    )
    active = sum(1 for r in rows if r.impl_status == "active")
    diverged = sum(1 for r in rows if r.impl_status == "diverged_pending")
    return active, diverged


def assert_concept_publishable(session: Session, concept_code: str) -> MetricConcept:
    """只校验不写库；失败抛 ValueError。"""
    c = get_concept(session, concept_code)
    if not c:
        raise ValueError(f"concept `{concept_code}` 不存在")
    active_n, diverged_n = _impl_counts(session, concept_code)
    metric_gate.validate_concept_publish(
        concept_code=c.concept_code,
        definition=c.definition,
        req_ref=c.req_ref,
        metric_kind=c.metric_kind,
        default_aggregation=c.default_aggregation,
        numerator_concept_code=c.numerator_concept_code,
        denominator_concept_code=c.denominator_concept_code,
        entity_code=c.entity_code,
        main_event_code=c.main_event_code,
        active_impl_count=active_n,
        diverged_pending_count=diverged_n,
    ).raise_if_failed()
    return c


def publish_concept(session: Session, concept_code: str, approver: User) -> MetricConcept:
    """draft → published；强制 G4+G5。"""
    c = assert_concept_publishable(session, concept_code)
    if c.lifecycle_status == "published":
        return c
    if c.lifecycle_status not in ("draft", "proposed"):
        raise ValueError(
            f"concept `{concept_code}` 当前 lifecycle={c.lifecycle_status}，不能 publish"
        )
    c.lifecycle_status = "published"
    c.approved_by = approver.id
    c.approved_at = datetime.now(timezone.utc)
    c.updated_at = datetime.now(timezone.utc)
    session.add(c)
    session.commit()
    session.refresh(c)
    return c


def set_implementation_primary(
    session: Session, *, concept_code: str, impl_id: int
) -> MetricImplementation:
    """设某实现为 primary；G5：有 diverged_pending 则拒绝。"""
    c = get_concept(session, concept_code)
    if not c:
        raise ValueError(f"concept `{concept_code}` 不存在")
    _, diverged_n = _impl_counts(session, concept_code)
    metric_gate.validate_set_primary(
        concept_code=concept_code, diverged_pending_count=diverged_n
    ).raise_if_failed()

    impl = session.get(MetricImplementation, impl_id)
    if not impl or impl.concept_code != concept_code:
        raise ValueError(f"implementation id={impl_id} 不属于 concept `{concept_code}`")
    if impl.impl_status != "active":
        raise ValueError(
            f"implementation id={impl_id} status={impl.impl_status}，仅 active 可设 primary"
        )

    others = list(
        session.exec(
            select(MetricImplementation).where(
                MetricImplementation.concept_code == concept_code
            )
        ).all()
    )
    for row in others:
        row.is_primary = row.id == impl_id
        row.updated_at = datetime.now(timezone.utc)
        session.add(row)
    session.commit()
    session.refresh(impl)
    return impl

