@router.get("/metric-library/concepts/{concept_code}")
def metric_library_concept_get(
    concept_code: str,
    user: User = Depends(require_api_user),
    session: Session = Depends(get_session),
) -> dict:
    r = metric_concept_layer_service.get_concept(session, concept_code)
    if not r:
        raise HTTPException(404, f"concept `{concept_code}` 不存在")
    return {
        "concept_code": r.concept_code,
        "definition": r.definition,
        "metric_kind": r.metric_kind,
        "numerator_concept_code": r.numerator_concept_code,
        "denominator_concept_code": r.denominator_concept_code,
        "default_aggregation": r.default_aggregation,
        "time_window": r.time_window,
        "layer": r.layer,
        "req_ref": r.req_ref,
        "lifecycle_status": r.lifecycle_status,
        "origin": r.origin,
        "version": r.version,
        "note": r.note,
        "entity_code": r.entity_code,
        "main_event_code": r.main_event_code,
        "related_event_codes": r.related_event_codes,
    }


class MetricLibraryPublishReq(BaseModel):
    concept_code: str


@router.post("/metric-library/concepts/publish")
def metric_library_concept_publish(
    req: MetricLibraryPublishReq,
    user: User = Depends(require_api_user),
    session: Session = Depends(get_session),
) -> dict:
    """概念层 published：强制 G4 四件套 + G5（无 diverged_pending）。"""
    if not user.is_admin:
        raise HTTPException(403, "仅 admin 能 publish 概念层指标")
    try:
        c = metric_concept_layer_service.publish_concept(session, req.concept_code, user)
    except ValueError as e:
        raise HTTPException(400, str(e))
    return {
        "ok": True,
        "concept_code": c.concept_code,
        "lifecycle_status": c.lifecycle_status,
    }


class MetricLibrarySetPrimaryReq(BaseModel):
    concept_code: str
    impl_id: int


@router.post("/metric-library/implementations/set-primary")
def metric_library_set_primary(
    req: MetricLibrarySetPrimaryReq,
    user: User = Depends(require_api_user),
    session: Session = Depends(get_session),
) -> dict:
    """设 primary：G5 — 有 diverged_pending 则拒绝。"""
    if not user.is_admin:
        raise HTTPException(403, "仅 admin 能设 primary")
    try:
        impl = metric_concept_layer_service.set_implementation_primary(
            session, concept_code=req.concept_code, impl_id=req.impl_id
        )
    except ValueError as e:
        raise HTTPException(400, str(e))
    return {
        "ok": True,
        "concept_code": impl.concept_code,
        "impl_id": impl.id,
        "is_primary": impl.is_primary,
    }
